// audio_ogg — embedded OGG Vorbis decoder (stb_vorbis) playing a sine tone
//
// stb_vorbis is a .c file from nothings/stb; the .h shim in
// audio_common/decoders/stb_vorbis.h makes it header-only via
// STB_VORBIS_HEADER_ONLY. The decoder and the OGG bytes are both
// compiled INTO the WASM data section.
//
// stb_vorbis needs a static scratch buffer for setup (no malloc
// because we build with -nostdlib). 256KB is plenty for a 1.5s
// 22kHz mono clip. The audio header is generated by
// audio_common/gen_audio.sh. SPACE restarts, ESC quits.

#include <stdint.h>

#include "../../audio_common/decoders/stb_vorbis.h"

#include "audio.h"

typedef struct { int x, y, w, h; } Rect;

uint32_t w_width       = 320;
uint32_t w_height      = 240;
uint32_t w_bpp         = 16;
uint32_t w_scale       = 2;
char     w_title[128]  = "Audio OGG (stb_vorbis)";
uint8_t  w_vram[320 * 240 * 2];
uint32_t w_dirty_count = 0;
Rect     w_dirty_rects[32];
int32_t  w_mouse_x = 0, w_mouse_y = 0;
uint32_t w_mouse_buttons = 0;
int32_t  w_mouse_wheel = 0;
uint8_t  w_keys[256] = {0};
uint32_t w_gamepad_buttons = 0;
uint32_t w_ticks = 0;

uint32_t w_audio_size        = 16384;
uint32_t w_audio_sample_rate = 22050;
uint32_t w_audio_bpp         = 2;
uint32_t w_audio_channels    = 1;
uint32_t w_audio_write       = 0;
uint32_t w_audio_read        = 0;
uint8_t  w_audio_buffer[16384];
uint32_t w_audio_underrun = 0;
uint32_t w_audio_overrun  = 0;

#define PCM_MAX_FRAMES (22050 * 2)
static int16_t  pcm[PCM_MAX_FRAMES * 2];
static uint32_t pcm_frames = 0;
static uint32_t play_pos   = 0;
static uint32_t src_rate   = 0;
static uint32_t src_ch     = 0;
static int      initialized = 0;

// stb_vorbis scratch buffer (avoids malloc under -nostdlib).
// Setup grows up from offset 0, temp allocations grow down from the end.
#define VORBIS_SCRATCH_SIZE (256 * 1024)
static unsigned char scratch[VORBIS_SCRATCH_SIZE];

static uint16_t* fb = (uint16_t*)w_vram;

static uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
    return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

static void set_pixel(int x, int y, uint16_t c) {
    if (x >= 0 && x < 320 && y >= 0 && y < 240) fb[y * 320 + x] = c;
}

static void fill_rect(int rx, int ry, int rw, int rh, uint16_t c) {
    for (int y = ry; y < ry + rh; y++)
        for (int x = rx; x < rx + rw; x++) set_pixel(x, y, c);
}

static const uint8_t font5x7[10][7] = {
    {0x0E,0x11,0x13,0x15,0x19,0x11,0x0E}, {0x04,0x0C,0x04,0x04,0x04,0x04,0x0E},
    {0x0E,0x11,0x01,0x06,0x08,0x10,0x1F}, {0x1F,0x02,0x04,0x02,0x01,0x11,0x0E},
    {0x02,0x06,0x0A,0x12,0x1F,0x02,0x02}, {0x1F,0x10,0x1E,0x01,0x01,0x11,0x0E},
    {0x06,0x08,0x10,0x1E,0x11,0x11,0x0E}, {0x1F,0x01,0x02,0x04,0x08,0x08,0x08},
    {0x0E,0x11,0x11,0x0E,0x11,0x11,0x0E}, {0x0E,0x11,0x11,0x0F,0x01,0x02,0x0C},
};

static void draw_digit(int x, int y, int d, uint16_t c) {
    if (d < 0 || d > 9) return;
    for (int row = 0; row < 7; row++)
        for (int col = 0; col < 5; col++)
            if (font5x7[d][row] & (0x10 >> col)) set_pixel(x + col, y + row, c);
}

static void draw_number(int x, int y, int n, uint16_t c) {
    if (n < 0) { set_pixel(x, y + 3, c); n = -n; x += 7; }
    if (n == 0) { draw_digit(x, y, 0, c); return; }
    char buf[12]; int len = 0;
    while (n > 0 && len < 12) { buf[len++] = n % 10; n /= 10; }
    for (int i = len - 1; i >= 0; i--) { draw_digit(x, y, buf[i], c); x += 6; }
}

static void init_audio(void) {
    stb_vorbis_alloc alloc;
    alloc.alloc_buffer = (char*)scratch;
    alloc.alloc_buffer_length_in_bytes = VORBIS_SCRATCH_SIZE;

    int err = 0;
    stb_vorbis* v = stb_vorbis_open_memory(audio_bin, audio_bin_len, &err, &alloc);
    if (!v) return;
    stb_vorbis_info info = stb_vorbis_get_info(v);
    src_rate = info.sample_rate;
    src_ch   = info.channels;

    uint32_t total = info.channels ? (uint32_t)stb_vorbis_stream_length_in_samples(v) : 0;
    if (total > PCM_MAX_FRAMES) total = PCM_MAX_FRAMES;
    int got = stb_vorbis_get_samples_short_interleaved(v, info.channels, pcm, (int)total);
    pcm_frames = got > 0 ? (uint32_t)got : 0;
    stb_vorbis_close(v);

    w_audio_sample_rate = src_rate;
    w_audio_channels    = src_ch;
    w_audio_bpp         = 2;
}

static void fill_audio(void) {
    if (!initialized || pcm_frames == 0) return;
    uint32_t r = w_audio_read, w = w_audio_write, sz = w_audio_size;
    if (sz < 2) return;
    uint32_t used = (w >= r) ? (w - r) : (sz - r + w);
    uint32_t free_s = (sz - 1) - used;
    uint32_t to_write = free_s > 2048 ? 2048 : free_s;
    if (to_write == 0) return;

    uint32_t sample_bytes = src_ch * 2;

    // Round to_write down to a whole-sample boundary so the host never
    // sees a half-written sample at the read pointer.
    to_write = (to_write / sample_bytes) * sample_bytes;
    if (to_write == 0) return;

    uint32_t i = 0;
    while (i < to_write) {
        uint32_t pos = (w + i) % sz;
        uint32_t to_end = sz - pos;

        // If we cannot fit a full sample before the wrap, stop here.
        // Better to underrun one frame than to corrupt a sample.
        if (to_end < sample_bytes) break;

        if (play_pos >= pcm_frames) play_pos = 0;
        const uint8_t* src = (const uint8_t*)&pcm[play_pos * src_ch];
        for (uint32_t b = 0; b < sample_bytes; b++)
            w_audio_buffer[pos + b] = src[b];
        i += sample_bytes;
        play_pos++;
    }
    w_audio_write = (w + i) % sz;
}

static void draw_ui(void) {
    fill_rect(0, 0, 320, 240, rgb565(15, 15, 20));

    // Format tag — OGG in green
    fill_rect(10, 10, 130, 25, rgb565(30, 30, 40));
    fill_rect(15, 15, 10, 10, rgb565(80, 220, 80));
    fill_rect(30, 15, 10, 10, rgb565(80, 80, 80));
    fill_rect(45, 15, 10, 10, rgb565(80, 80, 80));
    fill_rect(60, 15, 10, 10, rgb565(80, 80, 80));
    draw_number(80, 15, (int)(pcm_frames / 1000), rgb565(180, 180, 180));

    // Progress bar
    int ox = 10, oy = 60, bar_w = 300, bar_h = 15;
    fill_rect(ox, oy, bar_w, bar_h, rgb565(20, 20, 30));
    int fill_w = pcm_frames ? (int)((long)bar_w * play_pos / pcm_frames) : 0;
    fill_rect(ox, oy, fill_w, bar_h, rgb565(0, 180, 100));
    draw_number(ox,         oy + bar_h + 5, (int)play_pos, rgb565(180, 180, 180));
    draw_number(ox + 100,   oy + bar_h + 5, (int)pcm_frames, rgb565(100, 100, 100));
    draw_number(ox + 200,   oy + bar_h + 5, (int)src_rate, rgb565(255, 200, 0));

    // Waveform
    int woy = 110, h_h = 100;
    fill_rect(ox, woy, bar_w, h_h, rgb565(15, 15, 20));
    for (int x = 0; x < bar_w; x++) {
        uint32_t idx = pcm_frames ? (uint32_t)((long)x * pcm_frames / bar_w) : 0;
        int s = pcm[idx] / 256;
        int sy = woy + h_h/2 - s;
        if (sy >= woy && sy < woy + h_h) set_pixel(ox + x, sy, rgb565(0, 220, 150));
    }
}

int wupdate() {
    if (!initialized) { init_audio(); initialized = 1; }
    if (w_keys[41]) return 0;
    static int sp_was = 0;
    if (w_keys[44] && !sp_was) play_pos = 0;
    sp_was = w_keys[44];

    fill_audio();
    draw_ui();

    w_dirty_count = 1;
    w_dirty_rects[0] = (Rect){0, 0, 320, 240};
    return 1;
}
